/* From Uiverse.io by Praashoo7 - Tags: card, flip, realistic, creditcard */
.__UIV_SCOPE__ .flip-card {
  background-color: transparent;
  width: 240px;
  height: 154px;
  perspective: 1000px;
  color: white;
}

.__UIV_SCOPE__ .heading_8264 {
  position: absolute;
  letter-spacing: .2em;
  font-size: 0.5em;
  top: 2em;
  left: 18.6em;
}

.__UIV_SCOPE__ .logo {
  position: absolute;
  top: 6.8em;
  left: 11.7em;
}

.__UIV_SCOPE__ .chip {
  position: absolute;
  top: 2.3em;
  left: 1.5em;
}

.__UIV_SCOPE__ .contactless {
  position: absolute;
  top: 3.5em;
  left: 12.4em;
}

.__UIV_SCOPE__ .number {
  position: absolute;
  font-weight: bold;
  font-size: .6em;
  top: 8.3em;
  left: 1.6em;
}

.__UIV_SCOPE__ .valid_thru {
  position: absolute;
  font-weight: bold;
  top: 635.8em;
  font-size: .01em;
  left: 140.3em;
}

.__UIV_SCOPE__ .date_8264 {
  position: absolute;
  font-weight: bold;
  font-size: 0.5em;
  top: 13.6em;
  left: 3.2em;
}

.__UIV_SCOPE__ .name {
  position: absolute;
  font-weight: bold;
  font-size: 0.5em;
  top: 16.1em;
  left: 2em;
}

.__UIV_SCOPE__ .strip {
  position: absolute;
  background-color: black;
  width: 15em;
  height: 1.5em;
  top: 2.4em;
  background: repeating-linear-gradient(
    45deg,
    #303030,
    #303030 10px,
    #202020 10px,
    #202020 20px
  );
}

.__UIV_SCOPE__ .mstrip {
  position: absolute;
  background-color: rgb(255, 255, 255);
  width: 8em;
  height: 0.8em;
  top: 5em;
  left: .8em;
  border-radius: 2.5px;
}

.__UIV_SCOPE__ .sstrip {
  position: absolute;
  background-color: rgb(255, 255, 255);
  width: 4.1em;
  height: 0.8em;
  top: 5em;
  left: 10em;
  border-radius: 2.5px;
}

.__UIV_SCOPE__ .code {
  font-weight: bold;
  text-align: center;
  margin: .2em;
  color: black;
}

.__UIV_SCOPE__ .flip-card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: center;
  transition: transform 0.8s;
  transform-style: preserve-3d;
}

.__UIV_SCOPE__ .flip-card:hover .flip-card-inner {
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ .flip-card-front, .__UIV_SCOPE__ .flip-card-back {
  box-shadow: 0 8px 14px 0 rgba(0,0,0,0.2);
  position: absolute;
  display: flex;
  flex-direction: column;
  justify-content: center;
  width: 100%;
  height: 100%;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  border-radius: 1rem;
}

.__UIV_SCOPE__ .flip-card-front {
  box-shadow: rgba(0, 0, 0, 0.4) 0px 2px 2px, rgba(0, 0, 0, 0.3) 0px 7px 13px -3px, rgba(0, 0, 0, 0.2) 0px -1px 0px inset;
  background-color: #171717;
}

.__UIV_SCOPE__ .flip-card-back {
  box-shadow: rgba(0, 0, 0, 0.4) 0px 2px 2px, rgba(0, 0, 0, 0.3) 0px 7px 13px -3px, rgba(0, 0, 0, 0.2) 0px -1px 0px inset;
  background-color: #171717;
  transform: rotateY(180deg);
}
